def parse_curl_help_for_opts():
    try:
        proc = subprocess.run(["curl","--help","all"], capture_output=True, text=True, timeout=2)
        help_text = proc.stdout
    except:
        return set()
    opts_with = set()
    for line in help_text.splitlines():
        if '<' in line:
            flags = re.findall(r'(-\w|--[\w\-]+)\b', line)
            for f in flags:
                opts_with.add(f)
    return opts_with

CURL_OPTS_WITH_ARG = parse_curl_help_for_opts()

def is_curl_opt_with_arg(opt):
    if '=' in opt:
        base = opt.split('=',1)[0]
        return base in CURL_OPTS_WITH_ARG
    return opt in CURL_OPTS_WITH_ARG

def shell_quote(s):
    if ' ' in s:
        esc = s.replace('\\', '\\\\').replace('"', '\\"')
        return f'"{esc}"'
    else:
        return s

def header_quote(h):
    if ' ' in h:
        esc = h.replace('\\', '\\\\').replace('"', '\\"')
        return f'"{esc}"'
    else:
        return h

def json_quote(js):
    if ' ' in js:
        esc = js.replace('\\', '\\\\').replace('"', '\\"')
        return f'"{esc}"'
    else:
        return js

def url_encode(s):
